/**
 * Uses {@link ToEntriesArrayReadonly} to provide better typing for
 * {@link Object.fromEntries}.
 *
 * @category Functions – Object
 *
 * @since 2.0.0-beta.6
 */
export function objectFromEntries(entries) {
    return Object.fromEntries(entries);
}
